mapper.select:
SELECT h.history_seq as "historySeq", h.dm_id as "dmId", h.obj_owner as "objOwner", h.obj_nm as "objNm", h.attr_nm as "attrNm", h.input_kr_nm as "inputKrNm", h.resolved_kr_nm as "resolvedKrNm", h.resolved_en_nm as "resolvedEnNm", h.resolved_terms_id as "resolvedTermsId", COALESCE(d.data_type, h.resolved_data_type) as "resolvedDataType", COALESCE(d.data_len, h.resolved_data_len) as "resolvedDataLen", h.resolve_reason as "resolveReason", h.change_user_id as "changeUserId", h.change_dt as "changeDt", t.domain_nm as "resolvedDomainNm" FROM TB_TERM_RESOLVE_HISTORY h LEFT JOIN TB_TERMS t ON t.terms_id = h.resolved_terms_id LEFT JOIN TB_DOMAIN d ON d.domain_nm = t.domain_nm WHERE 1=1
AND h.change_user_id = #{currentUserId}
AND h.change_user_id = #{changeUserId}
AND h.dm_id = #{dmId}
AND h.input_kr_nm LIKE '%' || #{inputKrNm} || '%'
AND h.resolved_kr_nm LIKE '%' || #{resolvedKrNm} || '%'
AND h.resolved_en_nm ILIKE '%' || #{resolvedEnNm} || '%'
AND COALESCE(h.resolved_kr_nm,'') != COALESCE(h.input_kr_nm,'')
AND COALESCE(h.resolved_kr_nm,'') = COALESCE(h.input_kr_nm,'')
AND h.change_dt >= #{fromDt}
AND h.change_dt <= #{toDt}
ORDER BY h.history_seq DESC LIMIT 500
